102     template<typename FTy, typename CTy, typename CTr>
103     GLM_FUNC_QUALIFIER FTy const& get_facet(std::basic_ios<CTy, CTr>& ios)
104     {
105         if(!std::has_facet<FTy>(ios.getloc()))
106             ios.imbue(std::locale(ios.getloc(), new FTy));
107 
108         return std::use_facet<FTy>(ios.getloc());
109     }
