161     template<typename CTy, typename CTr, typename V>
162     GLM_FUNC_QUALIFIER std::basic_ostream<CTy, CTr>&
163     print_vector_on(std::basic_ostream<CTy, CTr>& os, V const& a)
164     {
165         typename std::basic_ostream<CTy, CTr>::sentry const cerberus(os);
166 
167         if(cerberus)
168         {
169             io::format_punct<CTy> const& fmt(io::get_facet<io::format_punct<CTy> >(os));
170 
171             length_t const& components(type<V>::components);
172 
173             if(fmt.formatted)
174             {
175                 io::basic_state_saver<CTy> const bss(os);
176 
177                 os << std::fixed << std::right << std::setprecision(static_cast<std::streamsize>(fmt.precision)) << std::setfill(fmt.space) << fmt.delim_left;
178 
179                 for(length_t i(0); i < components; ++i)
180                 {
181                     os << std::setw(static_cast<int>(fmt.width)) << a[i];
182                     if(components-1 != i)
183                         os << fmt.separator;
184                 }
185 
186                 os << fmt.delim_right;
187             }
188             else
189             {
190                 for(length_t i(0); i < components; ++i)
191                 {
192                     os << a[i];
193 
194                     if(components-1 != i)
195                         os << fmt.space;
196                 }
197             }
198         }
199 
200         return os;
201     }
202 }//namespace detail
