236     template<typename CTy, typename CTr, template<length_t, length_t, typename, qualifier> class M, length_t C, length_t R, typename T, qualifier Q>
237     GLM_FUNC_QUALIFIER std::basic_ostream<CTy, CTr>& print_matrix_on(std::basic_ostream<CTy, CTr>& os, M<C, R, T, Q> const& a)
238     {
239         typename std::basic_ostream<CTy,CTr>::sentry const cerberus(os);
240 
241         if(cerberus)
242         {
243             io::format_punct<CTy> const& fmt(io::get_facet<io::format_punct<CTy> >(os));
244 
245             length_t const& cols(type<M<C, R, T, Q> >::cols);
246             length_t const& rows(type<M<C, R, T, Q> >::rows);
247 
248             if(fmt.formatted)
249             {
250                 os << fmt.newline << fmt.delim_left;
251 
252                 switch(fmt.order)
253                 {
254                     case io::column_major:
255                     {
256                         for(length_t i(0); i < rows; ++i)
257                         {
258                             if (0 != i)
259                                 os << fmt.space;
260 
261                             os << row(a, i);
262 
263                             if(rows-1 != i)
264                                 os << fmt.newline;
265                         }
266                     }
267                     break;
268 
269                     case io::row_major:
270                     {
271                         for(length_t i(0); i < cols; ++i)
272                         {
273                             if(0 != i)
274                                 os << fmt.space;
275 
276                             os << column(a, i);
277 
278                             if(cols-1 != i)
279                                 os << fmt.newline;
280                         }
281                     }
282                     break;
283                 }
284 
285                 os << fmt.delim_right;
286             }
287             else
288             {
289                 switch (fmt.order)
290                 {
291                     case io::column_major:
292                     {
293                         for(length_t i(0); i < cols; ++i)
294                         {
295                             os << column(a, i);
296 
297                             if(cols - 1 != i)
298                                 os << fmt.space;
299                         }
300                     }
301                     break;
302 
303                     case io::row_major:
304                     {
305                         for (length_t i(0); i < rows; ++i)
306                         {
307                             os << row(a, i);
308 
309                             if (rows-1 != i)
310                                 os << fmt.space;
311                         }
312                     }
313                     break;
314                 }
315             }
316         }
317 
318         return os;
319     }
320 }//namespace detail
