376 namespace detail
377 {
378     template<typename CTy, typename CTr, template<length_t, length_t, typename, qualifier> class M, length_t C, length_t R, typename T, qualifier Q>
379     GLM_FUNC_QUALIFIER std::basic_ostream<CTy, CTr>& print_matrix_pair_on(std::basic_ostream<CTy, CTr>& os, std::pair<M<C, R, T, Q> const, M<C, R, T, Q> const> const& a)
380     {
381         typename std::basic_ostream<CTy,CTr>::sentry const cerberus(os);
382 
383         if(cerberus)
384         {
385             io::format_punct<CTy> const& fmt(io::get_facet<io::format_punct<CTy> >(os));
386             M<C, R, T, Q> const& ml(a.first);
387             M<C, R, T, Q> const& mr(a.second);
388             length_t const& cols(type<M<C, R, T, Q> >::cols);
389             length_t const& rows(type<M<C, R, T, Q> >::rows);
390 
391             if(fmt.formatted)
392             {
393                 os << fmt.newline << fmt.delim_left;
394 
395                 switch(fmt.order)
396                 {
397                     case io::column_major:
398                     {
399                         for(length_t i(0); i < rows; ++i)
400                         {
401                             if(0 != i)
402                                 os << fmt.space;
403 
404                             os << row(ml, i) << ((rows-1 != i) ? fmt.space : fmt.delim_right) << fmt.space << ((0 != i) ? fmt.space : fmt.delim_left) << row(mr, i);
405 
406                             if(rows-1 != i)
407                                 os << fmt.newline;
408                         }
409                     }
410                     break;
411                     case io::row_major:
412                     {
413                         for(length_t i(0); i < cols; ++i)
414                         {
415                             if(0 != i)
416                                 os << fmt.space;
417 
418                             os << column(ml, i) << ((cols-1 != i) ? fmt.space : fmt.delim_right) << fmt.space << ((0 != i) ? fmt.space : fmt.delim_left) << column(mr, i);
419 
420                             if(cols-1 != i)
421                                 os << fmt.newline;
422                         }
423                     }
424                     break;
425                 }
426 
427                 os << fmt.delim_right;
428             }
429             else
430             {
431                 os << ml << fmt.space << mr;
432             }
433         }
434 
435         return os;
436     }
437 }//namespace detail
